1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step =
11	  | { op: "quote"; items: Item[] }
12	  | { op: "claim"; policy: number; incident: Incident };
13	
14	export interface Item {
15	  type: string;
16	  material?: string;
17	  enchantment?: number;
18	  cursed?: boolean;
19	}
20	
21	export interface Damage {
22	  itemType: string;
23	  amount: number;
24	}
25	
26	export interface Incident {
27	  cause: string;
28	  damages: Damage[];
29	}
30	
31	export type Result = { premium: number } | { payout: number; remainingCap: number };
32	
33	const PROCESSING_FEE = 5;
34	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
35	
36	const BASE_PREMIUMS: Record<string, number> = {
37	  sword: 100,
38	  amulet: 60,
39	  staff: 80,
40	  potion: 40,
41	  rune: 25,
42	  moonstone: 25,
43	};
44	
45	// The MHPCO insures only what is on its price list.
46	export class UnknownItemTypeError extends Error {
47	  constructor(itemType: string) {
48	    super(`Unknown item type: ${itemType}`);
49	  }
50	}
51	
52	// The MHPCO's price lists are keyed by item type, and a type absent from a list
53	// is not insurable at all -- so every lookup is guarded the same way.
54	const priceListLookup =
55	  (priceList: Record<string, number>) =>
56	  (itemType: string): number => {
57	    const price = priceList[itemType];
58	    if (price === undefined) throw new UnknownItemTypeError(itemType);
59	    return price;
60	  };
61	
62	const basePremiumOf = priceListLookup(BASE_PREMIUMS);
63	
64	const COMPONENT_BLOCK_SIZE = 3;
65	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
66	
67	const CURSE_SURCHARGE_PERCENT = 50;
68	const HIGH_ENCHANTMENT_LEVEL = 5;
69	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
70	
71	// Each rule adds its percent of the item's *unmodified* base premium.
72	const ITEM_SURCHARGE_RULES: { applies: (item: Item) => boolean; percent: number }[] = [
73	  { applies: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
74	  {
75	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
76	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
77	  },
78	];
79	
80	const sumApplicablePercents = <T>(
81	  rules: { applies: (subject: T) => boolean; percent: number }[],
82	  subject: T,
83	): number =>
84	  rules.reduce(
85	    (percent, rule) => (rule.applies(subject) ? percent + rule.percent : percent),
86	    0,
87	  );
88	
89	const percentOf = (amount: number, percent: number): number =>
90	  (amount * percent) / 100;
91	
92	const groupByType = (items: Item[]): Item[][] => {
93	  const groups = new Map<string, Item[]>();
94	  for (const item of items) {
95	    const group = groups.get(item.type);
96	    if (group) group.push(item);
97	    else groups.set(item.type, [item]);
98	  }
99	  return [...groups.values()];
100	};
101	
102	const groupBasePremium = (group: Item[]): number =>
103	  group.length === COMPONENT_BLOCK_SIZE
104	    ? COMPONENT_BLOCK_BASE_PREMIUM
105	    : group.length * basePremiumOf(group[0].type);
106	
107	const policyBasePremium = (items: Item[]): number =>
108	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
109	
110	const itemSurchargePercent = (item: Item): number =>
111	  sumApplicablePercents(ITEM_SURCHARGE_RULES, item);
112	
113	const itemSurcharge = (item: Item): number =>
114	  percentOf(basePremiumOf(item.type), itemSurchargePercent(item));
115	
116	const totalItemSurcharges = (items: Item[]): number =>
117	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
118	
119	// The MHPCO always rounds in its own favour, keeping the fraction either way:
120	// money coming in rounds up, money going out rounds down.
121	const roundInMHPCOsFavour = {
122	  moneyIn: Math.ceil,
123	  moneyOut: Math.floor,
124	};
125	
126	const LOYALTY_YEARS = 2;
127	const LOYALTY_DISCOUNT_PERCENT = -20;
128	
129	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = -15;
130	
131	// What the MHPCO knows about the customer when a quote is issued: who they are,
132	// plus how many contracts they have already taken out in this scenario.
133	interface CustomerStanding {
134	  customer: Customer;
135	  previousContracts: number;
136	}
137	
138	// Signed percents of the *policy* base premium, driven by who the customer is
139	// rather than by what is insured. Negative percents are discounts.
140	const CUSTOMER_MODIFIER_RULES: {
141	  applies: (standing: CustomerStanding) => boolean;
142	  percent: number;
143	}[] = [
144	  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
145	  {
146	    applies: ({ customer }) => customer.yearsWithMHPCO >= LOYALTY_YEARS,
147	    percent: LOYALTY_DISCOUNT_PERCENT,
148	  },
149	  {
150	    applies: ({ previousContracts }) => previousContracts > 0,
151	    percent: FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
152	  },
153	];
154	
155	const customerModifierPercent = (standing: CustomerStanding): number =>
156	  sumApplicablePercents(CUSTOMER_MODIFIER_RULES, standing);
157	
158	const quotePremium = (items: Item[], standing: CustomerStanding): number => {
159	  const basePremium = policyBasePremium(items);
160	  return roundInMHPCOsFavour.moneyIn(
161	    basePremium +
162	      percentOf(basePremium, customerModifierPercent(standing)) +
163	      totalItemSurcharges(items) +
164	      PROCESSING_FEE,
165	  );
166	};
167	
168	const INSURANCE_VALUES: Record<string, number> = {
169	  sword: 1000,
170	  amulet: 600,
171	  staff: 800,
172	  potion: 400,
173	  rune: 250,
174	  moonstone: 250,
175	};
176	
177	const DEDUCTIBLE = 100;
178	const CAP_MULTIPLE = 2;
179	
180	const insuranceValueOf = priceListLookup(INSURANCE_VALUES);
181	
182	const insuranceSum = (items: Item[]): number =>
183	  items.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
184	
185	const REIMBURSED_ENCHANTMENT_LEVEL = 8;
186	const REIMBURSED_ENCHANTMENT_PERCENT = 50;
187	
188	// How much of a damage amount the MHPCO reimburses before the deductible.
189	const reimbursementPercent = (item: Item): number =>
190	  (item.enchantment ?? 0) >= REIMBURSED_ENCHANTMENT_LEVEL
191	    ? REIMBURSED_ENCHANTMENT_PERCENT
192	    : 100;
193	
194	// A damage report the MHPCO refuses to process.
195	export class InvalidDamageAmountError extends Error {
196	  constructor(amount: number) {
197	    super(`Invalid damage amount: ${amount}`);
198	  }
199	}
200	
201	// A damage entry must describe a loss, not a gain. One bad entry rejects the
202	// whole claim, so every entry is checked before any of them is settled.
203	const rejectInvalidDamages = (damages: Damage[]): void => {
204	  for (const { amount } of damages) {
205	    if (amount < 0) throw new InvalidDamageAmountError(amount);
206	  }
207	};
208	
209	const damagePayout = (damage: Damage, item: Item): number =>
210	  percentOf(damage.amount, reimbursementPercent(item)) - DEDUCTIBLE;
211	
212	// The MHPCO pays only for what it insures.
213	export class UninsuredItemError extends Error {
214	  constructor(itemType: string) {
215	    super(`Item not covered by the policy: ${itemType}`);
216	  }
217	}
218	
219	// The insured item a damage entry refers to. A damage entry naming a type the
220	// policy does not cover is not a payout of zero -- it is not insured at all.
221	// Each damage entry is settled against a distinct insured item, so a policy
222	// covering one sword cannot be claimed for two damaged swords.
223	const matchDamagesToInsuredItems = (
224	  damages: Damage[],
225	  insuredItems: Item[],
226	): { damage: Damage; item: Item }[] => {
227	  const unclaimed = [...insuredItems];
228	  return damages.map((damage) => {
229	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
230	    if (index === -1) throw new UninsuredItemError(damage.itemType);
231	    return { damage, item: unclaimed.splice(index, 1)[0] };
232	  });
233	};
234	
235	const claimPayout = (incident: Incident, insuredItems: Item[]): number =>
236	  matchDamagesToInsuredItems(incident.damages, insuredItems).reduce(
237	    (payout, { damage, item }) => payout + damagePayout(damage, item),
238	    0,
239	  );
240	
241	// The cap is 2 × the insurance sum of the insured items, unaffected by any
242	// premium modifiers.
243	const policyCap = (items: Item[]): number => CAP_MULTIPLE * insuranceSum(items);
244	
245	const settleClaim = (
246	  incident: Incident,
247	  insuredItems: Item[],
248	  capBefore: number,
249	): { payout: number; remainingCap: number } => {
250	  rejectInvalidDamages(incident.damages);
251	  const payout = roundInMHPCOsFavour.moneyOut(
252	    Math.min(claimPayout(incident, insuredItems), capBefore),
253	  );
254	  return { payout, remainingCap: capBefore - payout };
255	};
256	
257	// The cap left on each policy, keyed by the index of the quote step that
258	// created it. Successive claims against one policy draw down a shared cap.
259	const createCapLedger = () => {
260	  const remainingByPolicy = new Map<number, number>();
261	  return {
262	    open: (policyIndex: number, items: Item[]) =>
263	      remainingByPolicy.set(policyIndex, policyCap(items)),
264	    remainingOn: (policyIndex: number) => remainingByPolicy.get(policyIndex) ?? 0,
265	    drawDown: (policyIndex: number, remaining: number) =>
266	      remainingByPolicy.set(policyIndex, remaining),
267	  };
268	};
269	
270	// Contracts taken out before a given step: one per preceding quote.
271	const previousContractsAt = (steps: Step[], stepIndex: number): number =>
272	  steps.slice(0, stepIndex).filter((step) => step.op === "quote").length;
273	
274	// A claim step names its policy by the index of the quote step that created it.
275	const insuredItemsOf = (steps: Step[], policyIndex: number): Item[] => {
276	  const policyStep = steps[policyIndex];
277	  return policyStep.op === "quote" ? policyStep.items : [];
278	};
279	
280	export const runScenario = ({ customer, steps }: Scenario): { results: Result[] } => {
281	  const capLedger = createCapLedger();
282	
283	  const results = steps.map((step, stepIndex): Result => {
284	    if (step.op === "quote") {
285	      capLedger.open(stepIndex, step.items);
286	      return {
287	        premium: quotePremium(step.items, {
288	          customer,
289	          previousContracts: previousContractsAt(steps, stepIndex),
290	        }),
291	      };
292	    }
293	
294	    const settlement = settleClaim(
295	      step.incident,
296	      insuredItemsOf(steps, step.policy),
297	      capLedger.remainingOn(step.policy),
298	    );
299	    capLedger.drawDown(step.policy, settlement.remainingCap);
300	    return settlement;
301	  });
302	
303	  return { results };
304	};
305

