import re, io
p = 'src/claim-office.ts'
s = open(p).read()

old = '''// The insured item a damage entry refers to. A damage entry naming a type the
// policy does not cover is not a payout of zero -- it is not insured at all.
// Each damage entry is settled against a distinct insured item, so a policy
// covering one sword cannot be claimed for two damaged swords.
const matchDamagesToInsuredItems = (
  damages: Damage[],
  insuredItems: Item[],
): { damage: Damage; item: Item }[] => {
  const unclaimed = [...insuredItems];
  return damages.map((damage) => {
    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
    if (index === -1) throw new UninsuredItemError(damage.itemType);
    return { damage, item: unclaimed.splice(index, 1)[0] };
  });
};
'''

new = '''// A pool of insured items that each damage entry draws from. Claiming an item
// removes it from the pool, so a policy covering one sword cannot be claimed
// for two damaged swords. A type the pool cannot supply is not a payout of
// zero -- it is not insured at all.
const createUnclaimedItemPool = (insuredItems: Item[]) => {
  const unclaimed = [...insuredItems];
  return {
    claimOneOfType: (itemType: string): Item => {
      const index = unclaimed.findIndex((item) => item.type === itemType);
      if (index === -1) throw new UninsuredItemError(itemType);
      return unclaimed.splice(index, 1)[0];
    },
  };
};

// The insured item each damage entry is settled against -- a distinct one per
// entry.
const matchDamagesToInsuredItems = (
  damages: Damage[],
  insuredItems: Item[],
): { damage: Damage; item: Item }[] => {
  const unclaimedItems = createUnclaimedItemPool(insuredItems);
  return damages.map((damage) => ({
    damage,
    item: unclaimedItems.claimOneOfType(damage.itemType),
  }));
};
'''

assert old in s
open(p,'w').write(s.replace(old, new))
